SELECT count(*) FROM public.title title
  LEFT JOIN (SELECT key1, 1 AS hit FROM (SELECT cc.movie_id AS key1 FROM public.complete_cast cc, public.comp_cast_type cct1, public.comp_cast_type cct2 WHERE cct1.id = cc.subject_id AND cct2.id = cc.status_id AND cct1.kind = 'cast' INTERSECT SELECT ci.movie_id AS key1 FROM public.char_name chn, public.cast_info ci, public.name n WHERE chn.id = ci.person_role_id AND n.id = ci.person_id INTERSECT SELECT mk.movie_id AS key1 FROM public.keyword k, public.movie_keyword mk WHERE k.id = mk.keyword_id AND (k.keyword = 'superhero' OR k.keyword = 'sequel' OR k.keyword = 'second-part' OR k.keyword = 'marvel-comics' OR k.keyword = 'based-on-comic' OR k.keyword = 'tv-special' OR k.keyword = 'fight' OR k.keyword = 'violence')) x) b1 ON title.id = b1.key1
  LEFT JOIN (SELECT DISTINCT key1, 1 AS hit FROM (SELECT kt.id AS key1 FROM public.kind_type kt WHERE kt.kind = 'movie') x) b2 ON title.kind_id = b2.key1
WHERE (b2.hit IS NOT NULL AND b1.hit IS NOT NULL AND COALESCE(title.production_year > 1950, false));
